import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 1 Finding fossil man","description":"学习 推测情态动词与过去事件，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 1 Finding fossil man","description":"学习 推测情态动词与过去事件，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 推测情态动词与过去事件，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"第四册：流利英语 · Lesson 2 Spare that spider","link":"/life/english/new-concept/book-4/unit-01/lesson-002"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"第四册：流利英语 · Lesson 2 Spare that spider","link":"/life/english/new-concept/book-4/unit-01/lesson-002"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/lesson-001.md","filePath":"life/english/new-concept/book-4/unit-01/lesson-001.md"}'),o={name:"life/english/new-concept/book-4/unit-01/lesson-001.md"};function l(r,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-1-finding-fossil-man" tabindex="-1">第四册：流利英语 · Lesson 1 Finding fossil man <a class="header-anchor" href="#第四册-流利英语-·-lesson-1-finding-fossil-man" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 1 Finding fossil man&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以化石证据如何支持人类历史推断为阅读入口，区分留下来的物证与研究者提出的解释。学习在缺少直接观察时保留结论强度，用限定词说明发现能够证明什么、还不能证明什么，并练习按证据到推论的顺序写一段说明。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>fossil</td><td>/ˈfɒsəl/</td><td>n.</td><td>化石</td><td>fossil evidence</td></tr><tr><td>evidence</td><td>/ˈevɪdəns/</td><td>n.</td><td>证据</td><td>physical evidence</td></tr><tr><td>trace</td><td>/treɪs/</td><td>n.</td><td>痕迹</td><td>a trace of activity</td></tr><tr><td>infer</td><td>/ɪnˈfɜː/</td><td>v.</td><td>推断</td><td>infer from evidence</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>date back to — 追溯到，通常用现在时说明年代</li><li>in the absence of — 在缺乏某条件时</li></ul><h2 id="语法讲解-推测情态动词与过去事件" tabindex="-1">语法讲解：推测情态动词与过去事件 <a class="header-anchor" href="#语法讲解-推测情态动词与过去事件" aria-label="Permalink to &quot;语法讲解：推测情态动词与过去事件&quot;">​</a></h2><p>must have done 表示依据现有证据对过去作出较强推断，might have done 表示一种可能性，cannot have done 表示认为过去不可能如此。它们都不是对过去事实的直接报告。说明化石年代时，应先给观察再给推论；证据不足就不宜使用 must。must have left 不等于 had to leave，前者是推断离开过，后者是过去不得不离开。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The marks might have been made by tools, but their origin remains uncertain.</p></blockquote><p>这些痕迹可能是工具留下的，但其来源仍不确定。</p><p>might have been made 是情态动词加完成时被动结构；but 连接推测与限制；their 指 marks。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要把 might have been made 译成“必定是造成的”；might 保留了其他解释。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读示范，在 fragment、painted edge、might、uncertain 上重读；录音后检查 might have 是否被读成独立、断裂的三个音块。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>This fragment has a narrow painted edge. It might have belonged to a small bowl. Without the rest of the object, its use remains uncertain.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句博物馆展签：观察一个破损陶片，提出用途猜想，并说明缺少的证据。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>先描述可见特征，再用 might have belonged 表推断，最后说明结论边界。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：The bone may ___ belonged to a large animal.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 情态动词后接 have + 过去分词，构成对过去的推测。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例是否断言痕迹由工具造成？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有，只提出可能性。</p><p><strong>解析：</strong> might 与 uncertain 都限制了结论。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 They certainly had to leave. 中的“不得不离开”改成“可能已离开”：They ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> might have left</p><p><strong>解析：</strong> had to 表义务；might have done 表对过去的可能推测。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：推测情态动词与过去事件。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-01/lesson-002">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(o,[["render",l]]);export{u as __pageData,m as default};
